def max_non_overlapping(intervals):
    """Return the largest number of mutually non-overlapping intervals.

    Intervals are (start, end) pairs and are half-open, so (0, 3) and
    (3, 5) do not overlap. Input order is arbitrary.
    """
    intervals.sort()
    non_overlapping = []
    for start, end in intervals:
        if not non_overlapping or start >= non_overlapping[-1][1]:
            non_overlapping.append((start, end))
    return len(non_overlapping)

def max_non_overlapping(intervals):
    """Return the largest number of mutually non-overlapping intervals.

    Intervals are (start, end) pairs and are half-open, so (0, 3) and
    (3, 5) do not overlap. Input order is arbitrary.
    """
    intervals.sort()
    non_overlapping = []
    for start, end in intervals:
        if not non_overlapping or start >= non_overlapping[-1][1]:
            non_overlapping.append((start, end))
        else:
            non_overlapping[-1] = (non_overlapping[-1][0], max(non_overlapping[-1][1], end))
    return len(non_overlapping)

